fn branch_index(b: Branch) -> i64 {
    i64::try_from(Branch::ALL.iter().position(|&x| x == b).unwrap()).unwrap()
}

fn stem_index(st: Stem) -> i64 {
    i64::try_from(Stem::ALL.iter().position(|&x| x == st).unwrap()).unwrap()
}

/// The Tứ Hóa of a VN flow layer (Lộc, Quyền, Khoa, Kỵ) per stem, written out independently of
/// the engine: iztro's default, except Canh and Nhâm, which follow the Vietnamese school.
fn tu_hoa(st: Stem) -> [&'static str; 4] {
    match st {
        Stem::Jia => ["LiemTrinh", "PhaQuan", "VuKhuc", "ThaiDuong"],
        Stem::Yi => ["ThienCo", "ThienLuong", "TuVi", "ThaiAm"],
        Stem::Bing => ["ThienDong", "ThienCo", "VanXuong", "LiemTrinh"],
        Stem::Ding => ["ThaiAm", "ThienDong", "ThienCo", "CuMon"],
        Stem::Wu => ["ThamLang", "ThaiAm", "HuuBat", "ThienCo"],
        Stem::Ji => ["VuKhuc", "ThamLang", "ThienLuong", "VanKhuc"],
        Stem::Geng => ["ThaiDuong", "VuKhuc", "ThienDong", "ThaiAm"],
        Stem::Xin => ["CuMon", "ThaiDuong", "VanKhuc", "VanXuong"],
        Stem::Ren => ["ThienLuong", "TuVi", "ThienPhu", "VuKhuc"],
        Stem::Gui => ["PhaQuan", "CuMon", "ThaiAm", "ThamLang"],
    }
}

fn assert_tu_hoa(layer: &FlowLayer, what: &str) {
    let got: Vec<_> = layer.mutagens.iter().map(|(st, _)| st.key()).collect();
    let order: Vec<_> = layer.mutagens.iter().map(|&(_, m)| m).collect();
    assert_eq!(
        got,
        tu_hoa(layer.stem),
        "{what}: Tứ Hóa of {:?}",
        layer.stem
    );
    assert_eq!(order, Mutagen::ORDER, "{what}");
}

/// The VN flow follows the VN lunar date, including days where the VN calendar and the
/// engine's (official Chinese) calendar disagree, days in a VN-only leap month and VN day
/// 30s that need the 60-year shift. Checked with iztro's flow arithmetic:
/// yearly palace and stem = the lunar year's can chi; monthly palace = yearly - birth
/// month + birth hour + lunar month (a leap month's second half counts as the next
/// month); monthly stem by the five-tiger rule (五虎遁) from the year stem; daily palace =
/// monthly + lunar day - 1; daily stem = the day's can chi; each layer's Tứ Hóa is its
/// stem's.
#[test]
fn vn_flow_follows_the_vn_calendar() {
    use chart_svc::domain::calendar::year_can_chi;
    use time::Month::{April, December, February, March};
    let c = cases("vn")
        .into_iter()
        .find(|c| c["id"] == "vn-1985-02-01-male")
        .unwrap();
    let req = request(c, CalendarKind::Vn);
    let birth_month = i64::from(req.birth.lunar.month); // 1985-01-12, not leap
    let hour = branch_index(req.birth.hour_branch);
    let svc = service();
    let windows = [
        // VN Tết 1985 a month before CN; VN-only leap 2nd month; VN 1985-01-30 (shift).
        ((1985, February, 1), (1985, April, 30)),
        // VN Tết 2030 differs from CN.
        ((2029, December, 1), (2030, March, 31)),
    ];
    let (mut differing, mut leap_remapped, mut shifted) = (0, 0, 0);
    for ((y0, m0, d0), (y1, m1, d1)) in windows {
        let mut day = Date::from_calendar_date(y0, m0, d0).unwrap();
        let end = Date::from_calendar_date(y1, m1, d1).unwrap();
        while day <= end {
            let l = solar_to_lunar(day, CalendarKind::Vn);
            let engine = x_iztro::solar_to_lunar(
                i64::from(day.year()),
                u32::from(u8::from(day.month())),
                u32::from(day.day()),
            )
            .unwrap();
            if (u32::from(l.month), u32::from(l.day), l.leap)
                != (engine.lunar_month, engine.lunar_day, engine.is_leap)
            {
                differing += 1;
            }
            let fed = engine_lunar_date(l).unwrap();
            if l.leap && !fed.leap {
                leap_remapped += 1;
            }
            if fed.year != i64::from(l.year) {
                shifted += 1;
            }

            let f = svc.daily(&req, day).unwrap();
            let year = year_can_chi(l.year);
            let month = i64::from(l.month) + i64::from(l.leap && l.day > 15);
            let yearly = branch_index(f.yearly.palace_branch);
            assert_eq!(f.lunar, l, "{day}");
            assert_eq!(
                (f.yearly.stem, f.yearly.palace_branch),
                (year.stem, year.branch),
                "{day}"
            );
            assert_eq!(
                branch_index(f.monthly.palace_branch),
                (yearly - birth_month + hour + month).rem_euclid(12),
                "{day}"
            );
            // Five tigers: month 1 of a Giáp/Kỷ year is Bính Dần, so stem = 2·year + 1 + month.
            assert_eq!(
                stem_index(f.monthly.stem),
                (2 * stem_index(year.stem) + 1 + month).rem_euclid(10),
                "{day}: monthly stem"
            );
            assert_eq!(
                branch_index(f.daily.palace_branch),
                (branch_index(f.monthly.palace_branch) + i64::from(l.day) - 1).rem_euclid(12),
                "{day}"
            );
            assert_eq!(f.daily.stem, day_can_chi(day).stem, "{day}");
            for (name, layer) in [
                ("yearly", &f.yearly),
                ("monthly", &f.monthly),
                ("daily", &f.daily),
            ] {
                assert_tu_hoa(layer, &format!("{day} {name}"));
            }
            day = day.next_day().unwrap();
        }
    }
    assert!(
        differing > 0,
        "windows must include days the calendars disagree on"
    );
    assert!(
        leap_remapped > 0,
        "windows must include a VN-only leap month day"
    );
    assert!(
        shifted > 0,
        "windows must include a VN day 30 that needs the shift"
    );
}

#[test]
fn every_fixture_adjective_and_ring_star_has_a_key_and_label() {
    use chart_svc::domain::chart::{AdjStarKey, RingStarKey};
    let mut adjective = std::collections::HashSet::new();
    let mut rings = std::collections::HashSet::new();
    for c in fixture()["cases"].as_array().unwrap() {
        for p in c["expect"]["palaces"].as_array().unwrap() {
            for zh in p["adjective"].as_array().unwrap().iter().map(s) {
                if !VOID_STARS.contains(&zh) {
                    adjective.insert(adjective_key(zh));
                }
            }
            for list in ["changsheng12", "boshi12", "suiqian12", "jiangqian12"] {
                rings.insert(ring_key(s(&p[list])));
            }
        }
    }
    for key in &adjective {
        let star = AdjStarKey::ALL.iter().find(|k| k.key() == *key).unwrap();
        assert_ne!(star.name_vi(), "");
    }
    for key in &rings {
        let star = RingStarKey::ALL.iter().find(|k| k.key() == *key).unwrap();
        assert_ne!(star.name_vi(), "");
    }
    // The iztro fixture exercises every adjective star the domain knows except the
    // Vietnamese-only ones, and nothing else.
    assert_eq!(
        adjective.len(),
        AdjStarKey::ALL.iter().filter(|k| !k.is_vn_only()).count(),
        "adjective stars seen"
    );
    assert_eq!(rings.len(), RingStarKey::ALL.len(), "ring stars seen");
}

